from __future__ import annotations


def render_curation_page() -> str:
    """Professional local curation workspace; all media is addressed by project asset id."""
    return '''<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RAMBLA Curation</title><style>
:root{--bg:#0b0e12;--panel:#121821;--line:#273341;--ink:#edf2f7;--muted:#98a6b5;--lime:#d8ff5b;--danger:#ff7171}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Inter,system-ui,sans-serif}main{max-width:1600px;margin:auto;padding:20px}.top,.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between}.muted{color:var(--muted)}button,input{font:inherit}button{border:1px solid var(--line);border-radius:8px;padding:9px 12px;background:#202b37;color:var(--ink);font-weight:700;cursor:pointer}button.primary,button.active{background:var(--lime);color:#111}button:disabled{opacity:.5}.setup,.rail,.stage,.tray{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px;margin-top:15px}.grid{display:grid;grid-template-columns:260px minmax(0,1fr) 300px;gap:15px;margin-top:15px}.phrase{width:100%;text-align:left;margin:4px 0}.phrase small{display:block;color:var(--muted)}.phrase.selected{border-color:var(--lime)}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.card{padding:0;text-align:left;overflow:hidden}.card video,.card img{width:100%;height:110px;display:block;object-fit:cover;background:#202b37}.card .copy{padding:9px}.chip{border:1px solid var(--lime);border-radius:99px;padding:5px 8px;margin:3px;display:inline-flex;gap:5px}.error{color:var(--danger)}dialog{max-width:94vw;background:#111923;border:1px solid var(--line)}dialog img{max-width:88vw;max-height:85vh}@media(max-width:900px){.grid{grid-template-columns:1fr}.rail,.tray{order:2}}
</style><main><header class="top"><div><h1>RAMBLA Curation</h1><div class="muted">Editorial workspace · Resolve calls = 0</div></div><b id="save">Ready</b></header><section class="setup"><h2>New Reel</h2><div id="drop" class="row"><input id="file" type="file" accept="video/*"><button id="choose">Choose Video</button><button id="path">Open Local Path</button><input id="local" hidden placeholder="Path video locale"><button id="analyze" class="primary">ANALYZE REEL</button></div><div class="row"><video id="source" controls preload="metadata" hidden></video><span id="metadata" class="muted"></span><button disabled>Use Original Audio</button><button disabled>Replace Guide Audio</button></div></section><div class="grid"><aside class="rail"><b>PHRASES</b><div class="row"><button data-filter="all">All</button><button data-filter="needs">Needs Choice</button><button data-filter="selected">Selected</button><button data-filter="none">NO BROLL</button></div><div id="phrases"></div></aside><section class="stage"><div id="active" class="muted">Carica un reel per iniziare.</div><h3>VIDEO SUGGESTIONS</h3><div id="videos" class="cards"></div><h3>IMAGE SUGGESTIONS</h3><div id="images" class="cards"></div></section><aside class="tray"><b>SELECTION</b><div id="selected"></div><button id="none">NO BROLL</button><button id="confirm" class="primary">CONFIRM PLAN</button><p id="notice" class="muted"></p></aside></div></main><dialog id="lightbox"><button onclick="lightbox.close()">Close</button><img id="lightboxImage"></dialog><script>
const $=x=>document.getElementById(x),state={project:null,data:null,active:null,filter:'all',sel:new Map()};const api=(p,o)=>fetch('/api/curation'+p,o).then(async r=>{let j=await r.json();if(!r.ok)throw Error(j.detail||'Request failed');return j});const esc=x=>String(x??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));async function project(){if(!state.project)state.project=(await api('/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:'{"name":"New Reel"})).project_id;return state.project}function status(c){let s=state.sel.get(c.id);return s==='NO_BROLL'?'NO BROLL':s?.length?'Selected':'Needs Choice'}function draw(){let cs=(state.data?.chunks||[]).filter(c=>state.filter==='all'||(state.filter==='none'?status(c)==='NO BROLL':state.filter==='selected'?status(c)==='Selected':status(c)==='Needs Choice'));$('phrases').innerHTML=cs.map(c=>`<button class="phrase ${c.id===state.active?'selected':''}" data-c="${esc(c.id)}"><small>${esc(status(c))}</small>${esc(c.text||c.id)}</button>`).join('');document.querySelectorAll('.phrase').forEach(b=>b.onclick=()=>{state.active=b.dataset.c;draw()});let c=state.data?.chunks.find(x=>x.id===state.active)||cs[0];if(!c)return;state.active=c.id;$('active').innerHTML=`<h2>${esc(c.text||c.id)}</h2><span class=muted>${esc(c.id)}</span>`;let card=a=>{let media=a.kind==='video'?`<video muted loop playsinline preload="metadata" poster="${esc(a.poster_url)}" data-src="${esc(a.preview_url)}"></video>`:`<img loading="lazy" src="${esc(a.preview_url)}" alt="">`;return `<button class=card data-a="${esc(a.asset_id)}">${media}<div class=copy><b>${esc(a.title||a.provider)}</b><small>${esc(a.rights_state)}</small></div></button>`};$('videos').innerHTML=c.assets.filter(a=>a.kind==='video').slice(0,3).map(card).join('')||'<p class=muted>No video suggestions.</p>';$('images').innerHTML=c.assets.filter(a=>a.kind==='image').slice(0,4).map(card).join('')||'<p class=muted>No image suggestions.</p>';document.querySelectorAll('.card').forEach(b=>b.onclick=()=>pick(c.id,b.dataset.a));document.querySelectorAll('video[data-src]').forEach(v=>{v.onmouseenter=v.onfocus=()=>{v.src=v.dataset.src;v.play().catch(()=>{})};v.onmouseleave=v.onblur=()=>{v.pause();v.currentTime=0}});let chosen=state.sel.get(c.id)||[];$('selected').innerHTML=chosen==='NO_BROLL'?'<b>NO BROLL</b>':chosen.map((a,i)=>`<span class=chip>V${i+2} ${esc(a)} <button onclick="removeAsset('${esc(a)}')">×</button></span>`).join('')||'<p class=muted>Choose candidates in order.</p>'}async function save(c){$('save').textContent='Saving…';let v=state.sel.get(c);try{await api(`/projects/${state.project}/curation/chunks/${encodeURIComponent(c)}/selection`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset_ids:v==='NO_BROLL'?[]:v||[],no_broll:v==='NO_BROLL'})});$('save').textContent='Saved'}catch(e){$('save').textContent='Error — retry';$('notice').textContent=e.message}}async function pick(c,a){let x=state.sel.get(c);x=x==='NO_BROLL'?[]:(x||[]);state.sel.set(c,x.includes(a)?x.filter(v=>v!==a):[...x,a]);await save(c);draw()}window.removeAsset=async a=>{let x=state.sel.get(state.active)||[];state.sel.set(state.active,x.filter(v=>v!==a));await save(state.active);draw()};$('none').onclick=async()=>{state.sel.set(state.active,'NO_BROLL');await save(state.active);draw()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;draw()});$('choose').onclick=()=>$('file').click();$('path').onclick=()=>$('local').hidden=!$('local').hidden;$('file').onchange=async()=>{let f=$('file').files[0];if(!f)return;let p=await project();let r=await api(`/projects/${p}/source/upload?filename=${encodeURIComponent(f.name)}`,{method:'PUT',body:f});$('source').src=URL.createObjectURL(f);$('source').hidden=false;$('metadata').textContent=`${f.name} · ${r.source_video.width}×${r.source_video.height} · ${r.source_video.fps}fps`};$('analyze').onclick=async()=>{let p=await project();if($('local').value)await api(`/projects/${p}/source/local`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:$('local').value)});await api(`/projects/${p}/analyze`,{method:'POST'});state.data=await api(`/projects/${p}/curation`);for(let [k,v] of Object.entries(state.data.selection_plan?.chunks||{}))state.sel.set(k,v.no_broll?'NO_BROLL':v.selected_assets.map(x=>x.asset_id));state.active=state.data.chunks[0]?.id;draw()};$('confirm').onclick=()=>{$('notice').textContent=[...state.sel.values()].length?'Plan ready to confirm.':'Choose a candidate or NO BROLL for each phrase.'};
 </script></html>'''
